#include <bits/stdc++.h>
using namespace std;

struct Rectangle {
    int x1, y1, x2, y2;
};

class IndexedHeap {
    vector<int> heap;
    vector<int>& position;
    vector<int>& distance;

    void swapNodes(int a, int b) {
        swap(heap[a], heap[b]);
        position[heap[a]] = a;
        position[heap[b]] = b;
    }

    void siftUp(int i) {
        while (i > 0) {
            int p = (i - 1) / 2;
            if (distance[heap[p]] <= distance[heap[i]]) break;
            swapNodes(i, p);
            i = p;
        }
    }

    void siftDown(int i) {
        int n = (int)heap.size();
        while (true) {
            int smallest = i;
            int left = 2 * i + 1;
            int right = left + 1;
            if (left < n && distance[heap[left]] < distance[heap[smallest]])
                smallest = left;
            if (right < n && distance[heap[right]] < distance[heap[smallest]])
                smallest = right;
            if (smallest == i) break;
            swapNodes(i, smallest);
            i = smallest;
        }
    }

public:
    IndexedHeap(vector<int>& pos, vector<int>& dist, int capacity)
        : position(pos), distance(dist) {
        heap.reserve(capacity);
    }

    bool empty() const {
        return heap.empty();
    }

    void insertOrDecrease(int v) {
        if (position[v] == -1) {
            position[v] = (int)heap.size();
            heap.push_back(v);
        }
        siftUp(position[v]);
    }

    int pop() {
        int result = heap[0];
        position[result] = -2;
        if (heap.size() == 1) {
            heap.pop_back();
            return result;
        }

        heap[0] = heap.back();
        heap.pop_back();
        position[heap[0]] = 0;
        siftDown(0);
        return result;
    }
};

