    for (auto& r : rectangles) {
        cin >> r.x1 >> r.y1 >> r.x2 >> r.y2;
        xs.push_back(r.x1);
        xs.push_back(r.x2);
        ys.push_back(r.y1);
        ys.push_back(r.y2);
    }

