    rects.reserve(n);

    for (const auto& r : rectangles) {
        rects.push_back({
            (int)(lower_bound(xs.begin(), xs.end(), r.x1) - xs.begin()),
            (int)(lower_bound(ys.begin(), ys.end(), r.y1) - ys.begin()),
            (int)(lower_bound(xs.begin(), xs.end(), r.x2) - xs.begin()),
            (int)(lower_bound(ys.begin(), ys.end(), r.y2) - ys.begin())
        });
    }

    vector<unsigned char> horizontal((size_t)ny * max(0, nx - 1), 0);
