        for (int col = 0; col <= nx; ++col) {
            size_t p = (size_t)row * (nx + 1) + col;
            if (row > 0) diff[p] += diff[p - (nx + 1)];
            if (col > 0) diff[p] += diff[p - 1];
            if (row > 0 && col > 0) diff[p] -= diff[p - (nx + 2)];
        }
    }

