        for (int y = 0; y + 1 < ny; ++y) {
            vertical[(size_t)x * (ny - 1) + y] =
                diff[(size_t)x * (ny + 1) + y] > 0;
        }
    }

    int startX = lower_bound(xs.begin(), xs.end(), xi) - xs.begin();
    int startY = lower_bound(ys.begin(), ys.end(), yi) - ys.begin();
    int finishX = lower_bound(xs.begin(), xs.end(), xf) - xs.begin();
    int finishY = lower_bound(ys.begin(), ys.end(), yf) - ys.begin();

    int vertexCount = nx * ny;
    int start = startX * ny + startY;
    int finish = finishX * ny + finishY;

    const int INF = 1'000'000'000;
    vector<int> distance(vertexCount, INF);
    vector<int> position(vertexCount, -1);
    IndexedHeap heap(position, distance, vertexCount);

    distance[start] = 0;
    heap.insertOrDecrease(start);

    while (!heap.empty()) {
        int u = heap.pop();
        if (u == finish) break;

        int x = u / ny;
        int y = u % ny;

        auto relax = [&](int v, int cost) {
            int nd = distance[u] + cost;
            if (nd < distance[v] && position[v] != -2) {
                distance[v] = nd;
                heap.insertOrDecrease(v);
            }
        };

        if (x > 0) {
            bool covered = horizontal[(size_t)y * (nx - 1) + x - 1];
            relax(u - ny, covered ? 0 : xs[x] - xs[x - 1]);
        }
        if (x + 1 < nx) {
            bool covered = horizontal[(size_t)y * (nx - 1) + x];
            relax(u + ny, covered ? 0 : xs[x + 1] - xs[x]);
        }
        if (y > 0) {
            bool covered = vertical[(size_t)x * (ny - 1) + y - 1];
            relax(u - 1, covered ? 0 : ys[y] - ys[y - 1]);
        }
        if (y + 1 < ny) {
            bool covered = vertical[(size_t)x * (ny - 1) + y];
            relax(u + 1, covered ? 0 : ys[y + 1] - ys[y]);
        }
    }

    cout << distance[finish] << '\n';
    return 0;
}
